#[tokio::test]
async fn picker_view_returns_all_candidates_on_empty_query() {
    let (server, mut ws) = setup_picker_workspace().await;
    let view = send_request::<PickerView>(
        &mut ws,
        &PickerViewParams {
                view_id: None,
            limit: 30,
            ..view_params(PickerKind::Files)
        },
    )
    .await;
    assert_eq!(view.query, "");
    assert_eq!(view.effective_offset, 0);
    assert!(
        view.total_candidates >= 4,
        "expected >=4 candidates, got {}",
        view.total_candidates
    );
    // The window rides the response too, so a client whose local generation lags the resumed
    // picker still renders rows when the separate push races ahead and its staleness guard
    // discards it. It mirrors the push below.
    let embedded = view
        .update
        .as_ref()
        .expect("the view response carries its initial window");
    assert_eq!(embedded.kind, PickerKind::Files);
    assert_eq!(embedded.offset, 0);
    assert_eq!(embedded.total_candidates, view.total_candidates);
    assert!(!embedded.items().is_empty());

    let update: PickerUpdateParams = expect_notification::<PickerUpdate>(&mut ws).await;
    assert_eq!(update.kind, PickerKind::Files);
    assert_eq!(update.offset, 0);
    assert_eq!(update.total_candidates, view.total_candidates);
    assert_eq!(
        update.total_matches, view.total_candidates,
        "empty query matches all"
    );
    let names: Vec<&str> = update
        .items()
        .iter()
        .map(|i| {
            let PickerItem::File { relative_path, .. } = i else {
                panic!("expected File item, got {i:?}")
            };
            relative_path.as_str()
        })
        .collect();
    assert!(names.contains(&"src/main.rs"));
    assert!(names.contains(&"README.md"));

    drop(server);
}

/// A query change restarts the result list at the top: the pushed window is at offset 0 even when
/// the picker was scrolled down. The client resets its own offset to 0 on a keystroke, so a window
/// pushed at the old offset would be rejected (offset-mismatch guard) and leave stale rows on
/// screen. Resetting server-side keeps the two aligned so the fresh window lands.
#[tokio::test]
async fn picker_query_restarts_the_window_at_the_top() {
    let (server, mut ws) = setup_picker_workspace().await;
    // Subscribe a window scrolled down to offset 2.
    let view = send_request::<PickerView>(
        &mut ws,
        &PickerViewParams {
                view_id: None,
            offset: 2,
            limit: 2,
            ..view_params(PickerKind::Files)
        },
    )
    .await;
    assert_eq!(view.effective_offset, 2);
    let _ = expect_notification::<PickerUpdate>(&mut ws).await; // drain the view's own push

    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            filters: Default::default(),
            kind: PickerKind::Files,
            query: "r".into(),
            generation: 1,
        },
    )
    .await;
    let update = expect_notification::<PickerUpdate>(&mut ws).await;
    assert_eq!(
        update.offset, 0,
        "a query change windows from the top, not the prior scroll offset"
    );

    drop(server);
}

fn keybinding_rows() -> Vec<aether_protocol::picker::KeybindingEntry> {
    // A tiny stand-in keymap — the real client ships ~150 rows built from its tables, bucketed
    // by group (each group must be a contiguous run: one section header per run).
    [
        ("Editing", "Delete word back", "Any", "Ctrl-w"),
        ("Editing", "Newline and indent", "Insert", "Enter"),
        ("Pickers", "Find file", "Application", "Space f"),
    ]
    .into_iter()
    .map(
        |(group, desc, mode, keys)| aether_protocol::picker::KeybindingEntry {
            group: group.into(),
            desc: desc.into(),
            mode: mode.into(),
            keys: keys.into(),
        },
    )
    .collect()
}

fn keybindings_view_params(
    reset: PickerReset,
    rows: Option<Vec<aether_protocol::picker::KeybindingEntry>>,
) -> PickerViewParams {
    PickerViewParams {
            view_id: None,
        reset,
        limit: 30,
        keybindings: rows,
        ..view_params(PickerKind::Keybindings)
    }
}

/// The Keybindings picker matches over the whole composed row — group, description, mode, and
/// chord — and works *without* an active workspace (its rows are shipped by the client, and help
/// must be reachable from the pre-activation chooser, like the Workspaces picker).
#[tokio::test]
async fn keybindings_picker_matches_across_the_composed_row() {
    let dir = tempfile::tempdir().unwrap();
    let dir_path = dir.path().to_path_buf();
    let server = spawn_for_test("kb-proj", vec![dir_path]).await.unwrap();
    let mut ws = Ws::connect(&server).await;
    // Deliberately no `workspace/activate` before opening.

    let view = send_request::<PickerView>(
        &mut ws,
        &keybindings_view_params(PickerReset::All, Some(keybinding_rows())),
    )
    .await;
    assert_eq!(view.total_candidates, 3);
    let update = expect_notification::<PickerUpdate>(&mut ws).await;
    assert_eq!(update.kind, PickerKind::Keybindings);
    assert_eq!(update.total_matches, 3, "empty query lists every binding");
    // Empty query preserves the shipped (bucketed) order, and the display-row metrics count
    // one section header per group run: 3 items + 2 groups = 5 rows, the window's first item
    // sitting below the first header.
    let descs: Vec<&str> = update
        .items()
        .iter()
        .map(|i| {
            let PickerItem::Keybinding { desc, .. } = i else {
                panic!("expected Keybinding item, got {i:?}")
            };
            desc.as_str()
        })
        .collect();
    assert_eq!(
        descs,
        ["Delete word back", "Newline and indent", "Find file"]
    );
    assert_eq!(update.total_display_rows, Some(5));
    assert_eq!(update.display_offset, Some(1));
    // The group boundaries ride the push explicitly (window-relative starts) — clients render
    // these spans verbatim instead of re-deriving keys from item fields.
    use aether_protocol::picker::GroupHeader;
    let spans: Vec<(u32, &str)> = update
        .groups
        .iter()
        .map(|s| match &s.header {
            GroupHeader::Label { label } => (s.start, label.as_str()),
            GroupHeader::File { relative_path, .. } => (s.start, relative_path.as_str()),
        })
        .collect();
    assert_eq!(spans, [(0, "Editing"), (2, "Pickers")]);

    // A chord query: "ctrl" only matches the Ctrl-w row, and the match indices land in the
    // keys segment of the composed haystack ("Delete word back Ctrl-w").
    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            filters: Default::default(),
            kind: PickerKind::Keybindings,
            query: "ctrl".into(),
            generation: 1,
        },
    )
    .await;
    let update = expect_notification::<PickerUpdate>(&mut ws).await;
    assert_eq!(update.total_matches, 1);
    let PickerItem::Keybinding {
        keys,
        match_indices,
        ..
    } = &update.items()[0]
    else {
        panic!("expected Keybinding item")
    };
    assert_eq!(keys, "Ctrl-w");
    assert_eq!(
        match_indices,
        &[17, 18, 19, 20],
        "highlights 'Ctrl' in the chord"
    );

    // A mode query: Insert/Search rows carry their mode in the haystack ("Newline and indent
    // (Insert) Enter"), so "insert" narrows to them; default-mode rows elide theirs.
    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            filters: Default::default(),
            kind: PickerKind::Keybindings,
            query: "insert".into(),
            generation: 2,
        },
    )
    .await;
    let update = expect_notification::<PickerUpdate>(&mut ws).await;
    assert_eq!(update.total_matches, 1);
    let PickerItem::Keybinding { desc, .. } = &update.items()[0] else {
        panic!("expected Keybinding item")
    };
    assert_eq!(desc, "Newline and indent");

    drop(server);
}

