#[tokio::test]
async fn git_changes_picker_select_jumps_to_the_matched_line() {
    // Accepting a result during a content search lands on the matched line, not the hunk anchor.
    let dir = tempfile::tempdir().unwrap();
    git_commit_file(dir.path(), "a.rs", "l0\nl1\nl2\n");
    // Insert two lines after l0; the MARKER is on the *second* inserted line.
    std::fs::write(
        dir.path().join("a.rs"),
        "l0\nadded one\nadded two MARKER\nl1\nl2\n",
    )
    .unwrap();
    let dir_path = dir.path().to_path_buf();

    let server = spawn_for_test("jump-proj", vec![dir_path]).await.unwrap();
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "jump-proj".into(),
            open_last: false,
        },
    )
    .await;
    let _ = send_request::<PickerView>(
        &mut ws,
        &PickerViewParams {
                view_id: None,
            limit: 30,
            ..view_params(PickerKind::GitChanges)
        },
    )
    .await;
    let _ = expect_notification::<PickerUpdate>(&mut ws).await;
    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            filters: Default::default(),
            kind: PickerKind::GitChanges,
            query: "marker".into(),
            generation: 1,
        },
    )
    .await;
    let _: PickerUpdateParams = expect_notification::<PickerUpdate>(&mut ws).await;
    // Re-select the group and re-view to get its hunk row in hand.
    let (_, update) = expand_file_group(&mut ws, PickerKind::GitChanges, "a.rs").await;
    let item = update.items()[1].clone();
    let item_for_retry = serde_json::to_value(&item).unwrap();

    let result: PickerSelectResult = send_request::<PickerSelect>(
        &mut ws,
        &PickerSelectParams {
            kind: PickerKind::GitChanges,
            item,
        },
    )
    .await;
    let PickerSelectResult::FileAt { position, .. } = result else {
        panic!("expected FileAt, got {result:?}");
    };
    // The hunk anchors at line 1 (first inserted line); the match is on line 2 (second).
    assert_eq!(
        position.line, 2,
        "lands on the matched line, not the hunk anchor"
    );

    // Closing releases the candidate set, so the *same* select no longer resolves. This is why the
    // client sends `picker/select` before `picker/hide` on accept (`picker_accept`): behind the
    // close it would come back as this error instead of a jump.
    let _: () = send_request::<PickerHide>(
        &mut ws,
        &PickerHideParams {
            kind: PickerKind::GitChanges,
        },
    )
    .await;
    let req = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 6,
        "method": "picker/select",
        "params": { "kind": "git_changes", "item": item_for_retry },
    });
    ws.send(Message::text(serde_json::to_string(&req).unwrap()))
        .await
        .unwrap();
    let v: Value = serde_json::from_str(&next_text(&mut ws).await).unwrap();
    assert_eq!(
        v["error"]["code"], -32602,
        "a closed picker has nothing to resolve against"
    );

    drop(server);
}

#[tokio::test]
async fn git_changes_keep_view_preserves_query_within_one_open() {
    // A `Keep` re-view — a scroll refetch, within one open — comes back still filtered, with the
    // query echoed back, even though the candidates are re-snapshotted from the working tree.
    // (Closing wipes the picker, and a fresh open sends `All`; see
    // `changes_pickers_reopen_clean_and_rebuild_their_hunks`.)
    let dir = tempfile::tempdir().unwrap();
    git_commit_file(dir.path(), "a.rs", "alpha\n");
    std::fs::write(dir.path().join("a.rs"), "alpha MARKER\n").unwrap();
    std::fs::write(dir.path().join("b.rs"), "no match here\n").unwrap(); // untracked, no marker
    let dir_path = dir.path().to_path_buf();

    let server = spawn_for_test("persist-proj", vec![dir_path])
        .await
        .unwrap();
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "persist-proj".into(),
            open_last: false,
        },
    )
    .await;

    // Open (fresh), search "marker", then hide.
    let open = |reset| PickerViewParams {
            view_id: None,
        reset,
        limit: 30,
        ..view_params(PickerKind::GitChanges)
    };
    let _ = send_request::<PickerView>(&mut ws, &open(PickerReset::All)).await;
    let _ = expect_notification::<PickerUpdate>(&mut ws).await;
    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            filters: Default::default(),
            kind: PickerKind::GitChanges,
            query: "marker".into(),
            generation: 1,
        },
    )
    .await;
    let _ = expect_notification::<PickerUpdate>(&mut ws).await;

    // Re-view with `Keep` — the server kept the query, so the window comes back filtered.
    let view = send_request::<PickerView>(&mut ws, &open(PickerReset::Keep)).await;
    assert_eq!(
        view.query, "marker",
        "the content query survives a Keep re-view"
    );
    let update = view.update.expect("window rides the response");
    assert_eq!(
        group_rows(update.items()),
        vec![("a.rs".to_string(), 1, false)],
        "still filtered to the file with the matching hunk"
    );

    drop(server);
}

