/// Files and grep share one hidden-*inclusive* index; grep filters hidden files out in-memory for
/// its default. Intentional side effect (see `grep::FileFilter`): a dotfile whitelisted via a
/// `!`-rule in `.gitignore` — which the `ignore` crate lets override the hidden filter — no longer
/// appears in grep's default, only under `+hidden`.
#[tokio::test]
async fn grep_default_excludes_whitelisted_dotfile() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().to_path_buf();
    let repo = git2::Repository::init(&root).unwrap();
    std::fs::write(root.join("main.rs"), "needle here\n").unwrap();
    // `!.envrc` explicitly un-ignores it; the ignore crate treats that as "definitely include",
    // overriding its hidden-file default — so `.envrc` is in the inclusive walk.
    std::fs::write(root.join(".gitignore"), "!.envrc\n").unwrap();
    std::fs::write(root.join(".envrc"), "needle secret\n").unwrap();
    let mut index = repo.index().unwrap();
    for rel in ["main.rs", ".gitignore", ".envrc"] {
        index.add_path(std::path::Path::new(rel)).unwrap();
    }
    index.write().unwrap();
    let tree = repo.find_tree(index.write_tree().unwrap()).unwrap();
    let sig = git2::Signature::now("Test", "t@e.com").unwrap();
    repo.commit(Some("HEAD"), &sig, &sig, "init", &tree, &[])
        .unwrap();
    drop(tree);
    drop(index);
    drop(repo);

    let server = spawn_for_test("wl-proj", vec![root]).await.unwrap();
    let mut ws = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "wl-proj".into(),
            open_last: false,
        },
    )
    .await;
    let _ = send_request::<PickerView>(&mut ws, &view_params(PickerKind::Grep)).await;
    let _ = expect_notification::<PickerUpdate>(&mut ws).await; // initial empty push

    // Default: the whitelisted dotfile is NOT searched (grep default = no dotfiles).
    let update = grep_with_filters(&mut ws, "needle", PickerFilters::default(), 1).await;
    let files = grep_hit_files(&update);
    assert!(files.contains(&"main.rs".to_string()), "files: {files:?}");
    assert!(
        !files.contains(&".envrc".to_string()),
        "whitelisted dotfile excluded from grep default: {files:?}"
    );

    // `+hidden` brings it back — no re-walk needed, it's already in the inclusive snapshot.
    let filters = PickerFilters {
        include_hidden: true,
        ..Default::default()
    };
    let update = grep_with_filters(&mut ws, "needle", filters, 2).await;
    let files = grep_hit_files(&update);
    assert!(
        files.contains(&".envrc".to_string()),
        "+hidden surfaces the whitelisted dotfile: {files:?}"
    );

    drop(server);
}

/// A filter change with an unchanged query must not be served from the completed-search cache —
/// the candidates were produced under different filters.
#[tokio::test]
async fn grep_filter_change_invalidates_completed_search_cache() {
    let (server, mut ws) = setup_grep_filter_workspace().await;
    let update = grep_with_filters(&mut ws, "needle", PickerFilters::default(), 1).await;
    assert_eq!(update.total_matches, 7);
    // Same query, narrower filters → fresh search, fewer hits.
    let filters = PickerFilters {
        globs: vec!["*.md".into()],
        ..Default::default()
    };
    let update = grep_with_filters(&mut ws, "needle", filters.clone(), 2).await;
    assert_eq!(update.total_matches, 2);
    // Same query and same filters again → cache hit is fine; same results either way.
    let update = grep_with_filters(&mut ws, "needle", filters, 3).await;
    assert_eq!(update.total_matches, 2);
    drop(server);
}

/// A `Keep` re-view echoes the filters back alongside the query and hits, which is how a client
/// rebuilds its chip row from the server's copy rather than a local one. An `All` view wipes all
/// three.
#[tokio::test]
async fn grep_keep_view_echoes_filters_and_all_wipes_them() {
    let (server, mut ws) = setup_grep_filter_workspace().await;
    let filters = PickerFilters {
        whole_word: true,
        ..Default::default()
    };
    let update = grep_with_filters(&mut ws, "needle", filters.clone(), 1).await;
    assert_eq!(update.total_matches, 6);

    let resume: aether_protocol::picker::PickerViewResult = send_request::<PickerView>(
        &mut ws,
        &PickerViewParams {
                view_id: None,
            reset: PickerReset::Keep,
            ..view_params(PickerKind::Grep)
        },
    )
    .await;
    assert_eq!(resume.query, "needle");
    assert_eq!(resume.filters, filters, "filters echo back on a re-view");
    assert_eq!(resume.total_candidates, 6, "as do the hits they produced");
    let _ = expect_notification::<PickerUpdate>(&mut ws).await;

    let reset: aether_protocol::picker::PickerViewResult =
        send_request::<PickerView>(&mut ws, &view_params(PickerKind::Grep)).await;
    assert!(
        reset.filters.is_default(),
        "an `all` reset wipes filters too"
    );
    assert_eq!(reset.query, "");
    drop(server);
}

/// `picker/view { filters }` replaces the persisted set and, for grep, drops the cached hits
/// (they were produced under the old filters).
#[tokio::test]
async fn grep_view_with_filters_replaces_and_drops_stale_hits() {
    let (server, mut ws) = setup_grep_filter_workspace().await;
    let update = grep_with_filters(&mut ws, "needle", PickerFilters::default(), 1).await;
    assert_eq!(update.total_matches, 7);

    let scoped = PickerFilters {
        directories: vec![ScopedPath {
            path_index: 0,
            relative_path: "src".into(),
            is_file: false,
        }],
        ..Default::default()
    };
    let view: aether_protocol::picker::PickerViewResult = send_request::<PickerView>(
        &mut ws,
        &PickerViewParams {
                view_id: None,
            filters: Some(scoped.clone()),
            reset: PickerReset::Keep,
            ..view_params(PickerKind::Grep)
        },
    )
    .await;
    assert_eq!(view.filters, scoped);
    assert_eq!(
        view.total_candidates, 0,
        "stale hits dropped when filters change via view"
    );
    let _ = expect_notification::<PickerUpdate>(&mut ws).await;

    // Re-running the same query under the new filters yields the scoped result set.
    let update = grep_with_filters(&mut ws, "needle", scoped, 2).await;
    assert_eq!(update.total_matches, 3);
    drop(server);
}

/// Root scoping in a two-root workspace: a directory filter with an empty `relative_path`
/// (there is no separate root filter) searches only that root.
#[tokio::test]
async fn grep_filter_root_scope() {
    let dir_a = tempfile::tempdir().unwrap();
    let dir_b = tempfile::tempdir().unwrap();
    let (root_a, root_b) = (dir_a.path().to_path_buf(), dir_b.path().to_path_buf());
    std::fs::write(root_a.join("a.txt"), "needle in a\n").unwrap();
    std::fs::write(root_b.join("b.txt"), "needle in b\n").unwrap();
    let server = spawn_for_test("test-proj", vec![root_a, root_b])
        .await
        .unwrap();
    let mut ws = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: false,
        },
    )
    .await;
    let _ = send_request::<PickerView>(&mut ws, &view_params(PickerKind::Grep)).await;
    let _ = expect_notification::<PickerUpdate>(&mut ws).await;

    let filters = PickerFilters {
        directories: vec![ScopedPath {
            path_index: 1,
            relative_path: String::new(),
            is_file: false,
        }],
        ..Default::default()
    };
    let update = grep_with_filters(&mut ws, "needle", filters, 1).await;
    assert_eq!(update.total_matches, 1);
    match &update.items()[0] {
        PickerItem::Group {
            header:
                GroupHeader::File {
                    path_index,
                    relative_path,
                },
            count,
            ..
        } => {
            assert_eq!(*path_index, 1);
            assert_eq!(relative_path, "b.txt");
            assert_eq!(*count, 1);
        }
        other => panic!("expected b.txt's group header, got {other:?}"),
    }
    // Scopes in *different roots* union — the expressiveness globs can't reach (a glob is
    // root-relative but applies across all roots; only a dir scope pins one).
    let filters = PickerFilters {
        directories: vec![
            ScopedPath {
                path_index: 0,
                relative_path: String::new(),
                is_file: false,
            },
            ScopedPath {
                path_index: 1,
                relative_path: String::new(),
                is_file: false,
            },
        ],
        ..Default::default()
    };
    let update = grep_with_filters(&mut ws, "needle", filters, 2).await;
    assert_eq!(
        update.total_matches, 2,
        "both roots' hits under a cross-root union"
    );
    drop(server);
}

/// Files-picker filters reuse the grep filter workspace: directory scope, globs, changed-only,
/// and hide-hidden are pure predicates over the cached walk. The Files walk *includes* hidden
/// files (so tracked dot-entries are reachable); only ignored files are excluded at walk time, so
/// `+ignored` stays Grep-only. Dedicated hidden-dir coverage is `files_picker_shows_hidden_dirs`.
#[tokio::test]
async fn files_picker_filters_narrow_candidates() {
    let (server, mut ws) = setup_grep_filter_workspace().await;

    // Helper: send a files query with filters, return the final update for that generation.
    async fn files_query(
        ws: &mut Ws,
        query: &str,
        filters: PickerFilters,
        generation: u64,
    ) -> PickerUpdateParams {
        let _: () = send_request::<PickerQuery>(
            ws,
            &PickerQueryParams {
                kind: PickerKind::Files,
                query: query.into(),
                generation,
                filters,
            },
        )
        .await;
        loop {
            let params: PickerUpdateParams = expect_notification::<PickerUpdate>(ws).await;
            if params.generation == generation && !params.ticking {
                return params;
            }
        }
    }

    let _ = send_request::<PickerView>(&mut ws, &view_params(PickerKind::Files)).await;
    let first = expect_notification::<PickerUpdate>(&mut ws).await;
    // Default walk now includes the tracked hidden files (`.hidden.rs`, `.gitignore`) alongside
    // src/main.rs, src/lib.rs, README.md, changed.rs, new.rs; only gitignored `debug.log` and
    // `.git/` stay out.
    assert_eq!(first.total_matches, 7);

    // Directory scope: only src/ files.
    let filters = PickerFilters {
        directories: vec![ScopedPath {
            path_index: 0,
            relative_path: "src".into(),
            is_file: false,
        }],
        ..Default::default()
    };
    let update = files_query(&mut ws, "", filters, 1).await;
    assert_eq!(update.total_matches, 2);

    // Glob: .rs files only — composes with the fuzzy query.
    let filters = PickerFilters {
        globs: vec!["*.rs".into()],
        ..Default::default()
    };
    let update = files_query(&mut ws, "ma", filters.clone(), 2).await;
    let names: Vec<&str> = update
        .items()
        .iter()
        .filter_map(|i| match i {
            PickerItem::File { relative_path, .. } => Some(relative_path.as_str()),
            _ => None,
        })
        .collect();
    assert!(names.contains(&"src/main.rs"), "items: {names:?}");
    assert!(
        !names.contains(&"README.md"),
        "glob should drop README.md despite the fuzzy match: {names:?}"
    );

    // Changed-only: the modified + untracked files.
    let filters = PickerFilters {
        changed_only: true,
        ..Default::default()
    };
    let update = files_query(&mut ws, "", filters, 3).await;
    let names: Vec<&str> = update
        .items()
        .iter()
        .filter_map(|i| match i {
            PickerItem::File { relative_path, .. } => Some(relative_path.as_str()),
            _ => None,
        })
        .collect();
    assert_eq!(names, vec!["changed.rs", "new.rs"]);

    // Multiple dir scopes union: src/ plus the whole root widens back to the full walk (the
    // narrower scope doesn't subtract).
    let filters = PickerFilters {
        directories: vec![
            ScopedPath {
                path_index: 0,
                relative_path: "src".into(),
                is_file: false,
            },
            ScopedPath {
                path_index: 0,
                relative_path: String::new(),
                is_file: false,
            },
        ],
        ..Default::default()
    };
    let update = files_query(&mut ws, "", filters, 4).await;
    assert_eq!(update.total_matches, 7);

    // Hide-untracked alone: every tracked file stays, only the untracked new.rs drops — "all
    // tracked" (the orthogonal axis to changed-only).
    let filters = PickerFilters {
        hide_untracked: true,
        ..Default::default()
    };
    let update = files_query(&mut ws, "", filters, 5).await;
    let names: Vec<&str> = update
        .items()
        .iter()
        .filter_map(|i| match i {
            PickerItem::File { relative_path, .. } => Some(relative_path.as_str()),
            _ => None,
        })
        .collect();
    // Six tracked files (the two hidden ones included), only untracked new.rs drops.
    assert_eq!(update.total_matches, 6, "tracked-only: {names:?}");
    assert!(!names.contains(&"new.rs"), "untracked dropped: {names:?}");
    assert!(
        names.contains(&"changed.rs"),
        "tracked change kept: {names:?}"
    );

    // Changed-only composed with hide-untracked: changed *and* tracked — new.rs falls out, leaving
    // just the tracked modification.
    let filters = PickerFilters {
        changed_only: true,
        hide_untracked: true,
        ..Default::default()
    };
    let update = files_query(&mut ws, "", filters, 6).await;
    let names: Vec<&str> = update
        .items()
        .iter()
        .filter_map(|i| match i {
            PickerItem::File { relative_path, .. } => Some(relative_path.as_str()),
            _ => None,
        })
        .collect();
    assert_eq!(
        names,
        vec!["changed.rs"],
        "changed + tracked-only: {names:?}"
    );

    drop(server);
}

/// The Files picker surfaces tracked files inside *hidden directories* (e.g. `.circleci/`) by
/// default — the flip from the old ripgrep-style hidden exclusion — while still honouring
/// `.gitignore`. `Alt-.`'s `hide_hidden` chip filters them back out in-memory (no re-walk).
#[tokio::test]
async fn files_picker_shows_hidden_dirs() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().to_path_buf();

    let repo = git2::Repository::init(&root).unwrap();
    std::fs::create_dir_all(root.join(".circleci")).unwrap();
    std::fs::create_dir_all(root.join("src")).unwrap();
    std::fs::write(root.join(".circleci/workflows.yml"), "jobs: {}\n").unwrap();
    std::fs::write(root.join("src/main.rs"), "fn main() {}\n").unwrap();
    std::fs::write(root.join(".gitignore"), "secret.txt\n").unwrap();
    let mut index = repo.index().unwrap();
    for rel in [".circleci/workflows.yml", "src/main.rs", ".gitignore"] {
        index.add_path(std::path::Path::new(rel)).unwrap();
    }
    index.write().unwrap();
    let tree = repo.find_tree(index.write_tree().unwrap()).unwrap();
    let sig = git2::Signature::now("Test", "t@e.com").unwrap();
    repo.commit(Some("HEAD"), &sig, &sig, "init", &tree, &[])
        .unwrap();
    drop(tree);
    drop(index);
    drop(repo);
    // A gitignored file must never appear, even though hidden files now do.
    std::fs::write(root.join("secret.txt"), "nope\n").unwrap();

    let server = spawn_for_test("hidden-proj", vec![root]).await.unwrap();
    let mut ws = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "hidden-proj".into(),
            open_last: false,
        },
    )
    .await;

    let names_of = |u: &PickerUpdateParams| -> Vec<String> {
        u.items()
            .iter()
            .filter_map(|i| match i {
                PickerItem::File { relative_path, .. } => Some(relative_path.clone()),
                _ => None,
            })
            .collect()
    };

    // Default view: the hidden-dir file and the normal file both show; the gitignored file stays out.
    let _ = send_request::<PickerView>(&mut ws, &view_params(PickerKind::Files)).await;
    let first = expect_notification::<PickerUpdate>(&mut ws).await;
    let names = names_of(&first);
    assert!(
        names.iter().any(|n| n == ".circleci/workflows.yml"),
        "tracked file in a hidden dir shows by default: {names:?}"
    );
    assert!(names.iter().any(|n| n == "src/main.rs"), "{names:?}");
    assert!(
        !names.iter().any(|n| n == "secret.txt"),
        "gitignored file stays out even with hidden included: {names:?}"
    );

    // `hide_hidden` (the Alt-. chip) drops anything with a dot-component; normal files remain.
    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            kind: PickerKind::Files,
            query: String::new(),
            generation: 1,
            filters: PickerFilters {
                hide_hidden: true,
                ..Default::default()
            },
        },
    )
    .await;
    let hidden = loop {
        let p: PickerUpdateParams = expect_notification::<PickerUpdate>(&mut ws).await;
        if p.generation == 1 && !p.ticking {
            break p;
        }
    };
    let names = names_of(&hidden);
    assert!(
        !names.iter().any(|n| n == ".circleci/workflows.yml"),
        "hide_hidden drops the hidden-dir file: {names:?}"
    );
    assert!(
        names.iter().any(|n| n == "src/main.rs"),
        "hide_hidden keeps normal files: {names:?}"
    );

    drop(server);
}

/// Explorer filters: the listing shows hidden + ignored entries by default (colour-tagged), so
/// its chips hide them; changed-only keeps changed entries and ancestors of changes.
#[tokio::test]
async fn explorer_filters_hide_and_changed_only() {
    let (server, mut ws) = setup_grep_filter_workspace().await;

    async fn explorer_view(ws: &mut Ws, filters: Option<PickerFilters>) -> PickerUpdateParams {
        let _ = send_request::<PickerView>(
            ws,
            &PickerViewParams {
                    view_id: None,
                filters,
                reset: PickerReset::Keep,
                ..view_params(PickerKind::Explorer)
            },
        )
        .await;
        expect_notification::<PickerUpdate>(ws).await
    }

    fn entry_names(update: &PickerUpdateParams) -> Vec<&str> {
        update
            .items()
            .iter()
            .filter_map(|i| match i {
                PickerItem::DirEntry { name, .. } => Some(name.as_str()),
                _ => None,
            })
            .collect()
    }

    // Default: everything in the root, dotfiles and the ignored log included.
    let update = explorer_view(&mut ws, None).await;
    let names = entry_names(&update);
    assert!(names.contains(&".hidden.rs"), "names: {names:?}");
    assert!(names.contains(&"debug.log"), "names: {names:?}");

    // Hide hidden: dotfiles drop out (including .gitignore); the ignored log stays.
    let filters = PickerFilters {
        hide_hidden: true,
        ..Default::default()
    };
    let update = explorer_view(&mut ws, Some(filters)).await;
    let names = entry_names(&update);
    assert!(!names.contains(&".hidden.rs"), "names: {names:?}");
    assert!(!names.contains(&".gitignore"), "names: {names:?}");
    assert!(names.contains(&"debug.log"), "names: {names:?}");

    // Hide ignored: the log drops out; dotfiles return (filters were replaced whole).
    let filters = PickerFilters {
        hide_ignored: true,
        ..Default::default()
    };
    let update = explorer_view(&mut ws, Some(filters)).await;
    let names = entry_names(&update);
    assert!(!names.contains(&"debug.log"), "names: {names:?}");
    assert!(names.contains(&".hidden.rs"), "names: {names:?}");

    // Changed-only: changed/untracked files plus src/ (clean) is dropped; the ignored log is
    // not "changed".
    let filters = PickerFilters {
        changed_only: true,
        ..Default::default()
    };
    let update = explorer_view(&mut ws, Some(filters)).await;
    let names = entry_names(&update);
    assert_eq!(names, vec!["changed.rs", "new.rs"], "names: {names:?}");

    // Filters persist across re-views without an explicit set...
    let update = explorer_view(&mut ws, None).await;
    assert_eq!(entry_names(&update), vec!["changed.rs", "new.rs"]);

    // ...and a reset open clears them.
    let _ = send_request::<PickerView>(&mut ws, &view_params(PickerKind::Explorer)).await;
    let update = expect_notification::<PickerUpdate>(&mut ws).await;
    assert!(
        entry_names(&update).contains(&"src"),
        "reset restores the full listing"
    );

    // Changed-only composed with hide-untracked: the untracked new.rs drops out, leaving only the
    // tracked modification.
    let filters = PickerFilters {
        changed_only: true,
        hide_untracked: true,
        ..Default::default()
    };
    let update = explorer_view(&mut ws, Some(filters)).await;
    assert_eq!(
        entry_names(&update),
        vec!["changed.rs"],
        "changed + tracked-only"
    );

    drop(server);
}
